// 冷读只验证唯一原人和原抽样；当前玩家、钱货、角色和随机state均保持原值。
#include "family_birth_identity.hpp"
#include "resident/model/common_rng.hpp"
#include "resident/domains/growth/growth_skill_api.hpp"
#include <algorithm>
namespace hanmo::resident {
Status validate_birth_random_receipt(const CommonStore& c,const FamilyLineageCatalog& lineage,const FamilyBirthRecord& birth){if(birth.rng_stream!="world"||birth.rng_backend!="godot:4.7.2-stable (official)"||birth.rng_backend!=c.state().metadata.rng_backend)return common_failure("BirthRandomBackendMismatch");const auto* current=c.state().rng.find(birth.rng_stream);if(!current||current->seed!=birth.rng_seed||birth.innate.size()!=lineage.endowment.families.size())return common_failure("BirthRandomSourceMismatch");Integer state=birth.rng_before;for(const auto& family:lineage.endowment.families.rows()){const auto* result=birth.innate.find(family.first);if(!result||result->family_id!=family.first)return common_failure("BirthInnateFamilySetMismatch");auto draw=godot_pcg32_range(state,0,9999);if(!draw.ok)return {false,{},draw.error};if(result->draw!=draw.value.value)return common_failure("BirthInnateOriginalDrawMismatch",family.first);state=draw.value.next_state;auto valid=validate_birth_innate_result(lineage.endowment,*result);if(!valid.ok)return valid;}return state==birth.rng_after?common_success():common_failure("BirthRandomFinalStateMismatch");}
Status validate_biological_actor_identity(const CommonStore& c,const CommonCatalog& common,const FamilyCatalog& family,const FamilyLineageCatalog& lineage,const FamilyBirthState& births,const ActorRecord& actor){auto projection=read_birth_lineage_projection(c,common,lineage,births);if(!projection.ok)return {false,{},projection.error};const auto* source=projection.value.birth_sources.find(actor.id);const auto* birth=source?births.births.find(*source):nullptr;if(!birth||!actor.prototype_id||!actor.created_tick||!actor.birth_tick||!actor.display_name)return common_failure("BiologicalActorSourceRequired",actor.id);const auto* prototype=family.prototypes.find(birth->prototype_id);if(!prototype)return common_failure("UnknownBirthChildPrototype");auto valid=family_prototype_skill_eligibility(family,*prototype);if(!valid.ok)return valid;for(const auto& skill:growth_skill_ids(family.extended_skills))if(growth_skill_xp(prototype->skills,skill)!=0)return common_failure("BirthCannotInheritLearnedSkills",skill);if(actor.skills.extended.has_value()!=family.extended_skills)return common_failure("BiologicalActorSkillProfileMismatch");if(c.tick()-birth->tick<18*720&&actor.available)return common_failure("BiologicalMinorCannotBeAvailable",actor.id);if(actor.available&&c.tick()-birth->tick>=18*720){bool mature=false;for(const auto& row:births.maturations.rows())if(row.second.actor_id==actor.id){const auto* head=c.state().facts.find(row.first);if(!head||head->kind!="family_child_matured"||head->domain!="family_birth"||row.second.birth_fact_id!=*source||row.second.tick-birth->tick<18*720||row.second.tick>c.tick()||mature)return common_failure("BiologicalMaturationSourceRequired",actor.id);mature=true;}if(!mature)return common_failure("BiologicalMaturationSourceRequired",actor.id);}if(actor.wallet_id!="personal:"+actor.id||actor.inventory_id!="bag:"+actor.id)return common_failure("BiologicalActorPrivateAccountsMismatch",actor.id);return validate_birth_random_receipt(c,lineage,*birth);}
}
